package com.forward.hrms.employee.dto.request.travel.request;

import com.forward.hrms.employee.enums.travel.EntitlementType;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;

/**
 * Request payload used when a Travel Request entitlement needs to
 * be explicitly created or manually adjusted.
 *
 * <p>
 * Normally, Travel Request entitlements should be generated by the
 * Travel Service from the applicable Travel Policy and participant
 * information rather than being supplied directly by the client.
 *
 * <p>
 * The following values are intentionally NOT accepted from the client:
 *
 * <ul>
 *     <li>travelRequestId</li>
 *     <li>travelRequestParticipantId</li>
 *     <li>policyVersionId</li>
 *     <li>policyGradeLimitId</li>
 *     <li>employeeId</li>
 *     <li>grade snapshot information</li>
 *     <li>unit limit amount</li>
 *     <li>total limit amount</li>
 *     <li>policy unit limit amount</li>
 *     <li>calculation basis</li>
 *     <li>effective timestamp</li>
 *     <li>superseded information</li>
 * </ul>
 *
 * <p>
 * Those values are controlled by the Travel Service because they
 * must be derived from the selected participant, travel policy,
 * travel dates and applicable policy-grade rules.
 */
public record CreateTravelEntitlementRequest(

        /*
         * Business code identifying the participant's employee, e.g.
         * "EMP-100245". The Travel Service resolves this employee code to
         * the corresponding TravelRequestParticipant.
         */
        @NotBlank(message = "Employee code is required")
        @Size(max = 50, message = "Employee code must not exceed 50 characters")
        String employeeCode,

        /*
         * Entitlement category (ACCOMMODATION, BREAKFAST, LUNCH, DINNER,
         * OTHER, ...). The Travel Service validates it against the
         * applicable travel policy.
         */
        @NotNull(message = "Entitlement type code is required")
        EntitlementType entitlementTypeCode,

        /*
         * Number of units requested for this entitlement (e.g. 3 dinners
         * = 3, 2 accommodation nights = 2). The backend must validate the
         * quantity against the applicable travel dates and policy rules.
         */
        @NotNull(message = "Quantity allowed is required")
        @DecimalMin(value = "0", inclusive = true, message = "Quantity allowed cannot be negative")
        BigDecimal quantityAllowed,

        /*
         * Optional manually supplied unit amount for an entitlement that
         * is explicitly allowed to be adjusted by the business workflow.
         * For normal policy-derived entitlements this should be omitted
         * and the backend obtains the unit limit from
         * TravelPolicyGradeLimit.
         */
        @DecimalMin(value = "0", inclusive = true, message = "Unit limit amount cannot be negative")
        BigDecimal unitLimitAmount,

        /*
         * Optional currency override for a manually created entitlement.
         * For normal policy-generated entitlements the Travel Service
         * should use the Travel Request currency instead.
         */
        @Size(min = 3, max = 3, message = "Currency code must contain exactly 3 characters")
        String currencyCode,

        /*
         * Optional explanation supplied when the entitlement is being
         * manually created or adjusted.
         */
        String description
) {
}
